/* tchat : pour les joueurs qui ne sont pas en français, les messages des autres (et des bots) se traduisent tout seuls */
const AUTOTR={q:[],busy:0};
function autoTrPump(){if(AUTOTR.busy>=2||!AUTOTR.q.length)return;const el=AUTOTR.q.shift();if(!el||!el.isConnected||el.dataset.tro){autoTrPump();return}
  const x=el.dataset.trk,key=LANG+'|'+x;AUTOTR.busy++;
  const fin=t=>{AUTOTR.busy--;if(t&&el.isConnected&&!el.dataset.tro){el.dataset.tro=x;el.textContent=t;I18N.shown.add(key);const b=el.nextElementSibling;if(b&&b.dataset.a==='trmsg')b.textContent='↩︎'}setTimeout(autoTrPump,120)};
  const c=I18N.mem['m:'+key];if(c)return fin(c);if(I18N.mem['s:'+key])return fin(null);
  trText(x,'auto',LANG).then(r=>{if(!r||r.src===LANG||r.src===LANG.slice(0,2)){I18N.mem['s:'+key]=1;i18nSave();return fin(null)}I18N.mem['m:'+key]=r.t;i18nSave();fin(r.t)}).catch(()=>fin(null))}
{const mb=i18nMsgBtns;i18nMsgBtns=function(root){mb.apply(this,arguments);if(LANG==='fr'||!root||!root.querySelectorAll)return;try{root.querySelectorAll('.msg:not(.me):not(.sys) .tx[data-trk], .dmb:not(.me):not(.typing) > span[data-trk]').forEach(el=>{if(el.dataset.autotr)return;el.dataset.autotr=1;AUTOTR.q.push(el)});autoTrPump()}catch(e){}}}
